def test_runtime_planner_routes_data_analysis_artifact_to_communication() -> None:
    allowed_tools = [
        "data.analyze",
        "app.focus",
        "desktop.safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.submit_foreground",
        "terminal.run",
        "artifact.write",
    ]

    decision = RuntimePlanner().decision(
        "请分析 sales.csv 并把报告发给文件传输助手",
        allowed_tools=allowed_tools,
    )

    assert decision.selected_intent.kind == "data_analysis"
    assert decision.selected_intent.inputs["communication_target_hint"] == {
        "app_name": "WeChat",
        "recipient": "文件传输助手",
        "body_source": "analysis_artifact",
        "mode": "focus",
        "send_action": "send",
        "content_transform_hint": "report",
    }
    assert decision.plan.tool_plan.required_capabilities == [
        "data.analysis",
        "desktop.app_control",
        "communication.compose",
    ]
    assert [step.step_id for step in decision.plan.tool_plan.steps] == [
        "analyze-data-file",
        "open-or-focus-app",
        "focus-communication-recipient-search",
        "type-communication-recipient",
        "submit-communication-recipient-search",
        "draft-analysis-communication-message",
        "send-analysis-communication-message",
    ]
    assert _step_by_id(decision, "open-or-focus-app").input_preview == {
        "app_name": "WeChat"
    }
    assert _step_by_id(decision, "focus-communication-recipient-search").depends_on == [
        "open-or-focus-app"
    ]
    assert _step_by_id(decision, "type-communication-recipient").input_preview == {
        "text": "文件传输助手"
    }
    assert _step_by_id(decision, "draft-analysis-communication-message").input_preview == {
        "body_source": "analysis_artifact",
        "artifact_path": "analysis-report.md",
        "transform": "report",
    }
    send_step = _step_by_id(decision, "send-analysis-communication-message")
    assert send_step.approval_required is True
    assert send_step.risk_level == "high"

    slack_decision = RuntimePlanner().decision(
        "把 data/metrics.xlsx 分析成图表报告，然后发给 Slack 的 yachiyo",
        allowed_tools=allowed_tools,
    )

    assert slack_decision.selected_intent.kind == "data_analysis"
    assert slack_decision.selected_intent.inputs["communication_target_hint"] == {
        "app_name": "Slack",
        "recipient": "yachiyo",
        "body_source": "analysis_artifact",
        "mode": "focus",
        "send_action": "send",
        "content_transform_hint": "report",
    }
    assert slack_decision.plan.tool_plan.artifacts_expected == [
        "analysis-report.md",
        "analysis-chart.png",
    ]
    assert _step_by_id(slack_decision, "draft-analysis-communication-message").input_preview == {
        "body_source": "analysis_artifact",
        "artifact_path": "analysis-report.md",
        "transform": "report",
    }

    app_scoped_slack_decision = RuntimePlanner().decision(
        "把 data/metrics.xlsx 分析成图表报告，然后发给 Slack 的 yachiyo",
        allowed_tools=[
            "data.analyze",
            "app.focus",
            "app.focus_and_safe_shortcut",
            "app.focus_and_safe_type_text",
            "desktop.search_submit",
            "desktop.submit_foreground",
            "terminal.run",
            "artifact.write",
        ],
    )

    assert app_scoped_slack_decision.plan.tool_plan.missing_capabilities == []
    assert _step_by_id(
        app_scoped_slack_decision,
        "focus-communication-recipient-search",
    ).tool_name == "app.focus_and_safe_shortcut"
    assert _step_by_id(
        app_scoped_slack_decision,
        "type-communication-recipient",
    ).tool_name == "app.focus_and_safe_type_text"
    assert _step_by_id(
        app_scoped_slack_decision,
        "type-communication-recipient",
    ).input_preview == {
        "app_name": "Slack",
        "text": "yachiyo",
    }
    assert _step_by_id(
        app_scoped_slack_decision,
        "draft-analysis-communication-message",
    ).tool_name == "app.focus_and_safe_type_text"
    assert _step_by_id(
        app_scoped_slack_decision,
        "draft-analysis-communication-message",
    ).input_preview == {
        "app_name": "Slack",
        "body_source": "analysis_artifact",
        "artifact_path": "analysis-report.md",
        "transform": "report",
    }

    email_decision = RuntimePlanner().decision(
        "分析 data/sales.csv 并发邮件给 Alice 说明本周业绩",
        allowed_tools=allowed_tools,
    )

    assert email_decision.selected_intent.kind == "data_analysis"
    assert email_decision.selected_intent.inputs["communication_target_hint"] == {
        "recipient": "Alice",
        "body_source": "analysis_artifact",
        "mode": "focus",
        "send_action": "send",
        "channel": "email",
    }
    assert [step.step_id for step in email_decision.plan.tool_plan.steps] == [
        "analyze-data-file",
        "open-or-focus-app",
        "focus-communication-recipient-search",
        "type-communication-recipient",
        "submit-communication-recipient-search",
        "draft-analysis-communication-message",
        "send-analysis-communication-message",
    ]
    assert _step_by_id(email_decision, "open-or-focus-app").input_preview == {
        "app_name": "Mail"
    }
    assert _step_by_id(email_decision, "focus-communication-recipient-search").input_preview == {
        "action": "new_message"
    }
    assert _step_by_id(email_decision, "draft-analysis-communication-message").input_preview == {
        "body_source": "analysis_artifact",
        "artifact_path": "analysis-report.md",
    }


