def test_runtime_planner_timeline_preview_includes_created_plan_event() -> None:
    decision = RuntimePlanner().decision(
        "请分析 sales.csv 并输出一份数据分析报告",
        allowed_tools=["workspace.read", "terminal.run", "artifact.write"],
    )

    event_types = [event["event_type"] for event in decision.plan.timeline_preview]
    assert event_types == [
        "agent.intent.selected",
        "agent.plan.created",
        "agent.task_core.created",
        "agent.plan.step",
        "agent.plan.step",
        "agent.plan.step",
    ]
    created = decision.plan.timeline_preview[1]
    assert created["payload"]["plan_id"] == decision.plan.plan_id
    assert created["payload"]["tool_plan_id"] == decision.plan.tool_plan.plan_id
    assert created["payload"]["approvals_required"] == ["run-analysis"]
    assert created["payload"]["artifacts_expected"] == ["analysis-report.md"]
    assert created["payload"]["route_to_studio"] is True
    task_core_event = decision.plan.timeline_preview[2]
    assert task_core_event["payload"]["core_id"] == decision.plan.task_core.core_id
    assert task_core_event["payload"]["todo_count"] == 3
    assert task_core_event["payload"]["checkpoint_count"] == 4


def test_runtime_planner_emits_deepagent_style_task_core() -> None:
    decision = RuntimePlanner().decision(
        "请分析 sales.csv 并输出一份数据分析报告",
        allowed_tools=["workspace.read", "terminal.run", "artifact.write"],
    )

    task_core = decision.plan.task_core

    assert task_core is not None
    assert task_core.workspace.workspace_id.startswith("task-workspace-")
    assert [todo.step_id for todo in task_core.todos] == [
        "inspect-data-source",
        "run-analysis",
        "write-analysis-artifact",
    ]
    assert task_core.todos[1].approval_required is True
    assert any(item.kind == "input" and item.path == "sales.csv" for item in task_core.workspace.items)
    assert any(
        item.kind == "artifact"
        and item.path == "analysis-report.md"
        and item.source_step_id == "write-analysis-artifact"
        for item in task_core.workspace.items
    )
    run_input = next(
        item
        for item in task_core.workspace.items
        if item.title == "run-analysis.input.json"
    )
    assert run_input.kind == "scratch"
    assert run_input.source_step_id == "run-analysis"
    assert run_input.metadata["tool_name"] == "terminal.run"
    assert run_input.metadata["approval_required"] is True
    assert run_input.metadata["input_preview"] == {
        "command": "python - <<'PY'\n# inspect data, compute summary, generate charts\nPY"
    }
    assert [checkpoint.after_step_id for checkpoint in task_core.checkpoints[:3]] == [
        "inspect-data-source",
        "run-analysis",
        "write-analysis-artifact",
    ]
    assert any(signal.trigger == "tool_failure" for signal in task_core.replan_signals)


def test_runtime_planner_builds_replan_request_from_failed_step() -> None:
    decision = RuntimePlanner().decision(
        "请分析 sales.csv 并输出一份数据分析报告",
        allowed_tools=["workspace.read", "data.analyze", "terminal.run", "artifact.write"],
    )
    request_event = planner_replan_timeline_event(
        decision,
        {
            "event_type": "agent.tool.call",
            "step_id": "run-analysis",
            "tool_name": "data.analyze",
            "result": {"ok": False, "error": "unsupported chart type"},
        },
        run_id="run-1",
        task_id="task-1",
    )
    run_event = planner_replan_run_event_payload(
        decision,
        {
            "event_type": "agent.tool.call",
            "step_id": "run-analysis",
            "tool_name": "data.analyze",
            "result": {"ok": False, "error": "unsupported chart type"},
        },
    )

    assert request_event is not None
    assert request_event["event"] == "agent.replan.requested"
    payload = request_event["payload"]
    assert payload["trigger"] == "tool_failure"
    assert payload["run_id"] == "run-1"
    assert payload["task_id"] == "task-1"
    assert payload["decision_id"] == decision.decision_id
    assert payload["plan_id"] == decision.plan.plan_id
    assert payload["core_id"] == decision.plan.task_core.core_id
    assert payload["source_step_id"] == "run-analysis"
    assert payload["source_tool_name"] == "data.analyze"
    assert payload["target_capability_id"] == "data.analysis"
    assert payload["fallback_tools"] == ["terminal.run"]
    assert "unsupported chart type" in payload["failure_detail"]
    assert "Continue from the existing task workspace" in payload["replan_prompt"]
    task_context = payload["metadata"]["task_core_context"]
    assert task_context["core_id"] == decision.plan.task_core.core_id
    assert task_context["workspace_id"] == decision.plan.task_core.workspace.workspace_id
    assert task_context["workspace_title"] == "Data Analysis Workspace"
    assert task_context["source_step_id"] == "run-analysis"
    assert task_context["planner_step_id"] == "analyze-data-file"
    assert any(
        item["kind"] == "input" and item["path"] == "sales.csv"
        for item in task_context["workspace_items"]
    )
    assert task_context["todos"][0]["step_id"] == "analyze-data-file"
    assert task_context["checkpoints"][0]["after_step_id"] == "analyze-data-file"
    assert task_context["replan_signals"][0]["fallback_tools"] == ["terminal.run"]
    assert "Task workspace context:" in payload["replan_prompt"]
    assert "- planner_step: analyze-data-file" in payload["replan_prompt"]
    assert "input · planned · sales.csv" in payload["replan_prompt"]
    assert "analyze-data-file · pending · data.analyze" in payload["replan_prompt"]
    assert run_event is not None
    assert run_event[0] == "agent.replan.requested"
    assert run_event[1]["request_id"] == payload["request_id"]


def test_runtime_planner_timeline_events_include_full_studio_trace_payloads() -> None:
    decision = RuntimePlanner().decision(
        "打开 PixelForge 并点击导出按钮",
        allowed_tools=["app.open", "desktop.click_ui_element"],
    )

    events = planner_timeline_events(decision)

    assert [event["event"] for event in events[:4]] == [
        "agent.intent.selected",
        "agent.plan.created",
        "agent.task_core.created",
        "agent.plan.step",
    ]
    assert events[0]["payload"]["intent"]["kind"] == "desktop_operation"
