    assert [request["tool"] for request in generic_requests] == [
        "desktop.list_apps",
        "app.open_and_safe_shortcut",
        "desktop.ui_elements",
    ]
    assert generic_requests[0]["continue_to_model"] is True
    assert generic_requests[-1]["continue_to_model"] is True
