def test_runtime_planner_routes_explicit_terminal_command_to_approval_plan() -> None:
    decision = RuntimePlanner().decision(
        "打开终端运行 ls",
        allowed_tools=["app.open", "desktop.list_apps", "terminal.run"],
    )
    terminal_app_command = RuntimePlanner().decision(
        "帮我打开一个终端应用运行 ls",
        allowed_tools=["app.open", "desktop.list_apps", "terminal.run"],
    )
    bare_command = RuntimePlanner().decision(
        "运行 ls 看一下当前目录",
        allowed_tools=["terminal.run", "workspace.list", "artifact.write"],
    )
    command_with_followup = RuntimePlanner().decision(
        "打开终端运行 pwd 并把结果告诉我",
        allowed_tools=["app.open", "desktop.list_apps", "terminal.run"],
    )

    assert decision.selected_intent.kind == "code_task"
    assert decision.selected_intent.title == "Terminal Command"
    assert decision.selected_intent.inputs == {
        "terminal_command_hint": {"command": "ls"}
    }
    assert decision.plan.route_to_studio is True
    assert decision.plan.tool_plan.required_capabilities == ["terminal.execution"]
    assert decision.plan.tool_plan.approvals_required == ["run-terminal-command"]
    assert [step.step_id for step in decision.plan.tool_plan.steps] == [
        "run-terminal-command"
    ]
    step = _step_by_id(decision, "run-terminal-command")
    assert step.tool_name == "terminal.run"
    assert step.input_preview == {"command": "ls"}
    assert step.approval_required is True
    for extra_decision in (terminal_app_command, bare_command):
        assert extra_decision.selected_intent.kind == "code_task"
        assert extra_decision.selected_intent.title == "Terminal Command"
        assert extra_decision.selected_intent.inputs == {
            "terminal_command_hint": {"command": "ls"}
        }
        assert _step_by_id(extra_decision, "run-terminal-command").tool_name == (
            "terminal.run"
        )
    assert command_with_followup.selected_intent.kind == "code_task"
    assert command_with_followup.selected_intent.inputs == {
        "terminal_command_hint": {"command": "pwd"}
    }
    assert _step_by_id(
        command_with_followup,
        "run-terminal-command",
    ).input_preview == {"command": "pwd"}
    assert planner_direct_tool_requests(
        "run npm test in terminal",
        ["terminal.run"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "terminal.run",
            "input": {"command": "npm test"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_terminal_command",
        }
    ]
    assert planner_tool_requests("运行 ls 看一下当前目录", ["terminal.run"]) == [
        {
            "protocol": "json_fallback",
            "tool": "terminal.run",
            "input": {"command": "ls"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_terminal_command",
        }
    ]
    assert planner_tool_requests("打开终端运行 pwd 并把结果告诉我", ["terminal.run"]) == [
        {
            "protocol": "json_fallback",
            "tool": "terminal.run",
            "input": {"command": "pwd"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_terminal_command",
        }
    ]
    assert planner_direct_tool_requests("run npm test and summarize failures", ["terminal.run"]) == [
        {
            "protocol": "json_fallback",
            "tool": "terminal.run",
            "input": {"command": "npm test"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_terminal_command",
        }
    ]


def test_runtime_planner_plans_code_changes_after_workspace_inspection() -> None:
    decision = RuntimePlanner().decision(
        "帮我写一个 Python 脚本处理日志",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    writable_decision = RuntimePlanner().decision(
        "帮我写一个 Python 脚本处理日志",
        allowed_tools=[
            "workspace.list",
            "workspace.read",
            "workspace.write_patch",
            "terminal.run",
            "artifact.write",
        ],
    )

    assert decision.selected_intent.kind == "code_task"
    assert decision.selected_intent.inputs == {
        "code_change_hint": {"mode": "create"}
    }
    assert decision.plan.tool_plan.required_capabilities == [
        "file.workspace_read",
        "file.workspace_write",
    ]
    assert decision.plan.tool_plan.missing_capabilities == ["file.workspace_write"]
    assert decision.plan.tool_plan.approvals_required == ["apply-code-changes"]
    assert [step.step_id for step in decision.plan.tool_plan.steps] == [
        "inspect-workspace",
        "apply-code-changes",
    ]
    assert _step_by_id(decision, "inspect-workspace").tool_name == "workspace.list"
    assert _step_by_id(decision, "apply-code-changes").tool_name is None
    assert _step_by_id(decision, "apply-code-changes").status == "unavailable"
    assert all(step.tool_name != "terminal.run" for step in decision.plan.tool_plan.steps)
    assert all(step.step_id != "write-code-report" for step in decision.plan.tool_plan.steps)
    assert _step_by_id(writable_decision, "apply-code-changes").tool_name == (
        "workspace.write_patch"
    )
    assert _step_by_id(writable_decision, "apply-code-changes").approval_required is True
    assert [step.step_id for step in writable_decision.plan.tool_plan.steps] == [
        "inspect-workspace",
        "apply-code-changes",
    ]


def test_runtime_planner_routes_code_test_diagnostics_to_approval_terminal_plan() -> None:
    decision = RuntimePlanner().decision(
        "修复这个仓库里的 failing tests",
        allowed_tools=[
            "workspace.list",
            "workspace.read",
            "workspace.write_patch",
            "terminal.run",
            "artifact.write",
        ],
    )
    run_tests = RuntimePlanner().decision(
        "运行这个仓库的测试",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )

    assert decision.selected_intent.kind == "code_task"
    assert decision.selected_intent.inputs == {
        "code_diagnostic_command_hint": {"command": "python -m pytest"},
        "code_change_hint": {"mode": "fix"},
    }
    assert decision.selected_intent.expected_outputs == ["patch", "test_output"]
    assert decision.selected_intent.required_capabilities == [
        "file.workspace_read",
        "file.workspace_write",
        "terminal.execution",
    ]
    assert decision.plan.tool_plan.required_capabilities == [
        "file.workspace_read",
        "terminal.execution",
        "file.workspace_write",
    ]
    assert decision.plan.tool_plan.approvals_required == [
        "run-code-diagnostic",
        "apply-code-changes",
        "verify-code-changes",
    ]
    assert [step.step_id for step in decision.plan.tool_plan.steps] == [
        "inspect-workspace",
        "run-code-diagnostic",
        "apply-code-changes",
        "verify-code-changes",
    ]
    assert decision.plan.timeline_preview[1]["payload"]["runtime_doctrine"] == (
        "discover_operate_verify"
    )
    assert decision.plan.timeline_preview[1]["payload"]["runtime_stage_counts"] == {
        "discover": 2,
        "operate": 1,
        "verify": 1,
    }
    assert {
        todo.step_id: (
            todo.metadata.get("runtime_stage"),
            todo.metadata.get("runtime_role"),
        )
        for todo in decision.plan.task_core.todos
    } == {
        "inspect-workspace": ("discover", "inspect_workspace"),
        "run-code-diagnostic": ("discover", "diagnose"),
        "apply-code-changes": ("operate", "apply_patch"),
        "verify-code-changes": ("verify", "verify_result"),
    }
    run_step = _step_by_id(decision, "run-code-diagnostic")
    assert run_step.tool_name == "terminal.run"
    assert run_step.input_preview == {"command": "python -m pytest"}
    assert run_step.depends_on == ["inspect-workspace"]
    assert run_step.approval_required is True
    apply_step = _step_by_id(decision, "apply-code-changes")
    assert apply_step.tool_name == "workspace.write_patch"
    assert apply_step.input_preview == {
        "mode": "fix",
        "patch_source": "model_after_workspace_inspection",
    }
    assert apply_step.depends_on == ["run-code-diagnostic"]
    assert apply_step.approval_required is True
    verify_step = _step_by_id(decision, "verify-code-changes")
    assert verify_step.tool_name == "terminal.run"
    assert verify_step.input_preview == {"command": "python -m pytest"}
    assert verify_step.depends_on == ["apply-code-changes"]
    assert verify_step.approval_required is True
    assert all(step.step_id != "write-code-report" for step in decision.plan.tool_plan.steps)
    assert run_tests.selected_intent.inputs == {
        "code_diagnostic_command_hint": {"command": "python -m pytest"}
    }
    assert [step.step_id for step in run_tests.plan.tool_plan.steps] == [
        "inspect-workspace",
        "run-code-diagnostic",
        "write-code-report",
    ]
    assert _step_by_id(run_tests, "write-code-report").tool_name == "artifact.write"
    assert planner_tool_requests(
        "修复这个仓库里的 failing tests",
        [
            "workspace.list",
            "workspace.read",
            "workspace.write_patch",
            "terminal.run",
            "artifact.write",
        ],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_code_context",
            "step_id": "inspect-workspace",
            "capability_id": "file.workspace_read",
        },
        {
            "protocol": "json_fallback",
            "tool": "terminal.run",
            "input": {"command": "python -m pytest"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_code_diagnostic",
            "continue_to_model": True,
            "step_id": "run-code-diagnostic",
            "capability_id": "terminal.execution",
        }
    ]


def test_runtime_planner_routes_local_file_access_to_desktop_file_tools() -> None:
    open_decision = RuntimePlanner().decision(
        "打开当前选中的 Finder 文件",
        allowed_tools=["desktop.open_path", "desktop.reveal_path"],
    )

    assert open_decision.selected_intent.kind == "file_access"
    assert open_decision.selected_intent.inputs == {
        "action": "open_path",
        "path": "finder_selection",
    }
    open_step = _step_by_id(open_decision, "open-local-path")
    assert open_step.capability_id == "file.desktop_access"
    assert open_step.tool_name == "desktop.open_path"
    assert open_step.action == "open_path"
    assert open_step.input_preview == {"path": "finder_selection"}
    assert open_decision.plan.route_to_studio is False

    reveal_decision = RuntimePlanner().decision(
        "在 Finder 中显示 iCloud 云盘",
        allowed_tools=["desktop.open_path", "desktop.reveal_path"],
    )

    assert reveal_decision.selected_intent.kind == "file_access"
    assert reveal_decision.selected_intent.inputs == {
        "action": "reveal_path",
        "path": "~/Library/Mobile Documents/com~apple~CloudDocs",
    }
    reveal_step = _step_by_id(reveal_decision, "reveal-local-path")
    assert reveal_step.tool_name == "desktop.reveal_path"
    assert reveal_step.action == "reveal_path"
    assert reveal_step.input_preview == {
        "path": "~/Library/Mobile Documents/com~apple~CloudDocs"
    }


def test_runtime_planner_requires_file_location_for_file_organization() -> None:
    decision = RuntimePlanner().decision(
        "整理文件并删除重复项",
        allowed_tools=["workspace.list", "artifact.write"],
    )

    assert decision.selected_intent.kind == "file_organization"
    assert decision.selected_intent.missing_inputs == ["file_location"]
    assert decision.selected_intent.risk_level == "high"
    assert _step_by_id(decision, "apply-file-organization").status == "unavailable"


