def test_runtime_planner_cleans_web_research_query_and_tracks_delivery_target() -> None:
    allowed = [
        "browser.open_url",
        "artifact.write",
        "app.focus",
        "desktop.safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.submit_foreground",
    ]

    generic_target = RuntimePlanner().decision(
        "调研 OpenAI 最新价格，整理成表格和报告，然后发给 Alice",
        allowed_tools=allowed,
    )
    wechat_target = RuntimePlanner().decision(
        "调研 OpenAI 最新价格，整理成表格和报告，然后发给微信文件传输助手",
        allowed_tools=allowed,
    )

    assert generic_target.selected_intent.kind == "web_research"
    assert generic_target.selected_intent.inputs == {
        "url_hint": "https://www.google.com/search?q=OpenAI+%E6%9C%80%E6%96%B0%E4%BB%B7%E6%A0%BC",
        "communication_target_hint": {
            "recipient": "Alice",
            "body_source": "research_artifact",
            "mode": "focus",
            "send_action": "send",
            "content_transform_hint": "report",
        },
        "browser_action": "open_search",
        "query": "OpenAI 最新价格",
    }
    assert generic_target.selected_intent.expected_outputs == ["report", "table"]
    assert [step.step_id for step in generic_target.plan.tool_plan.steps] == [
        "open-web-search",
        "write-research-artifact",
        "draft-research-communication",
    ]
    assert _step_by_id(generic_target, "draft-research-communication").input_preview == {
        "recipient": "Alice",
        "body_source": "research_artifact",
        "artifact_path": "research-summary.md",
        "transform": "report",
    }
    assert _step_by_id(generic_target, "draft-research-communication").approval_required is True

    generic_app_target = RuntimePlanner().decision(
        "调研 OpenAI 最新价格，整理成报告，然后发到任意聊天应用给 Alice",
        allowed_tools=[*allowed, "desktop.list_apps", "app.open"],
    )
    assert generic_app_target.selected_intent.inputs["communication_target_hint"] == {
        "recipient": "Alice",
        "body_source": "research_artifact",
        "mode": "focus",
        "send_action": "send",
        "channel": "message",
        "content_transform_hint": "report",
    }
    assert [
        step.step_id
        for step in generic_app_target.plan.tool_plan.steps[-7:]
    ] == [
        "discover-research-communication-app",
        "open-or-focus-research-communication-app",
        "focus-research-communication-recipient-search",
        "type-research-communication-recipient",
        "submit-research-communication-recipient-search",
        "draft-research-communication-message",
        "send-research-communication-message",
    ]
    assert _step_by_id(generic_app_target, "discover-research-communication-app").input_preview == {
        "query": "chat",
        "limit": 20,
    }
    assert _step_by_id(generic_app_target, "open-or-focus-research-communication-app").input_preview == {
        "app_name": "<selected app from desktop.list_apps>",
        "selection_source": "desktop.list_apps",
        "query": "chat",
    }
    assert planner_tool_requests(
        "调研 OpenAI 最新价格，整理成表格和报告，然后发给 Alice",
        allowed_tools=allowed,
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "browser.open_url",
            "input": {
                "url": "https://www.google.com/search?q=OpenAI+%E6%9C%80%E6%96%B0%E4%BB%B7%E6%A0%BC"
            },
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_web_research",
            "continue_to_model": True,
        }
    ]

    assert wechat_target.selected_intent.inputs["communication_target_hint"] == {
        "recipient": "文件传输助手",
        "body_source": "research_artifact",
        "mode": "focus",
        "send_action": "send",
        "app_name": "WeChat",
        "content_transform_hint": "report",
    }
    assert [step.step_id for step in wechat_target.plan.tool_plan.steps] == [
        "open-web-search",
        "write-research-artifact",
        "open-or-focus-research-communication-app",
        "focus-research-communication-recipient-search",
        "type-research-communication-recipient",
        "submit-research-communication-recipient-search",
        "draft-research-communication-message",
        "send-research-communication-message",
    ]
    assert _step_by_id(wechat_target, "send-research-communication-message").approval_required is True


def test_runtime_planner_keeps_app_scoped_searches_executable_and_observable() -> None:
    allowed = [
        "desktop.list_apps",
        "app.open",
        "app.focus",
        "desktop.safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.ui_elements",
        "artifact.write",
        "screen.capture",
        "desktop.running_apps",
    ]

    pixel_forge = RuntimePlanner().decision(
        "打开一个叫 PixelForge 的应用，搜索 export settings，然后把当前结果总结成报告",
        allowed_tools=allowed,
    )

    assert pixel_forge.selected_intent.kind == "desktop_operation"
    assert pixel_forge.selected_intent.inputs == {
        "app_name_hint": "PixelForge",
        "operation_hint": "open",
        "app_search_hint": {"query": "export settings", "target": "搜索"},
        "desktop_content_artifact_hint": {
            "path": "desktop-content-report.md",
            "body_source": "desktop_content",
        },
    }
    assert pixel_forge.selected_intent.expected_outputs == ["report"]
    assert [step.step_id for step in pixel_forge.plan.tool_plan.steps] == [
        "discover-desktop-state",
        "open-or-focus-app",
        "focus-opened-app",
        "focus-app-search-field",
        "type-app-search-query",
        "submit-app-search",
        "read-desktop-content",
        "write-desktop-content-artifact",
    ]
    assert _step_by_id(pixel_forge, "type-app-search-query").input_preview == {
        "text": "export settings"
    }
    assert _step_by_id(pixel_forge, "read-desktop-content").tool_name == (
        "desktop.ui_elements"
    )
    assert _step_by_id(pixel_forge, "write-desktop-content-artifact").input_preview == {
        "path": "desktop-content-report.md",
        "body_source": "desktop_content",
    }

    system_settings = RuntimePlanner().decision(
        "打开系统设置",
        allowed_tools=[*allowed, "system.settings_open"],
    )
    assert system_settings.selected_intent.kind == "system_control"
    assert system_settings.selected_intent.inputs["kind"] == "settings_open"


