def test_runtime_planner_pastes_dynamic_context_into_discovered_apps() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]

    clipboard = RuntimePlanner().decision(
        "把剪贴板内容写进一个笔记应用",
        allowed_tools=allowed_tools,
    )
    current_link = RuntimePlanner().decision(
        "找一个笔记应用，把当前网页链接写进去",
        allowed_tools=allowed_tools,
    )
    selected_text = RuntimePlanner().decision(
        "找一个文本编辑器，把选中的文字写进去",
        allowed_tools=allowed_tools,
    )

    assert clipboard.selected_intent.kind == "desktop_operation"
    assert clipboard.selected_intent.inputs["dynamic_context_ui_transfer_hint"]["source"] == (
        "clipboard"
    )
    assert [step.step_id for step in clipboard.plan.tool_plan.steps] == [
        "discover_apps-desktop-state",
        "open-selected-discovered-app",
        "paste-context-into-selected-discovered-app",
        "verify-selected-discovered-app-action",
    ]
    assert _step_by_id(clipboard, "open-selected-discovered-app").input_preview == {
        "app_name": "<selected app from desktop.list_apps>",
        "selection_source": "desktop.list_apps",
        "query": "notes",
    }
    assert _step_by_id(
        clipboard,
        "paste-context-into-selected-discovered-app",
    ).input_preview == {"action": "paste"}
    assert "type-selected-discovered-app-text" not in {
        step.step_id for step in clipboard.plan.tool_plan.steps
    }
    clipboard_requests = planner_tool_requests(
        "把剪贴板内容写进一个笔记应用",
        allowed_tools,
    )
    assert [request["tool"] for request in clipboard_requests] == [
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]
    assert clipboard_requests[2]["input"] == {"action": "paste"}
    assert all("continue_to_model" not in request for request in clipboard_requests)

    assert current_link.selected_intent.inputs["dynamic_context_ui_transfer_hint"] == {
        "source": "current_page_link",
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": "笔记",
        "mode": "focus",
    }
    assert [step.step_id for step in current_link.plan.tool_plan.steps] == [
        "copy-current-page-link-context",
        "discover_apps-desktop-state",
        "open-selected-discovered-app",
        "paste-context-into-selected-discovered-app",
        "verify-selected-discovered-app-action",
    ]
    assert _step_by_id(current_link, "discover_apps-desktop-state").depends_on == [
        "copy-current-page-link-context"
    ]
    current_link_requests = planner_tool_requests(
        "找一个笔记应用，把当前网页链接写进去",
        allowed_tools,
    )
    assert [request["tool"] for request in current_link_requests] == [
        "desktop.safe_shortcut",
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]
    assert current_link_requests[0]["input"] == {"action": "copy_current_page_link"}
    assert current_link_requests[3]["input"] == {"action": "paste"}
    assert all("continue_to_model" not in request for request in current_link_requests)

    assert selected_text.selected_intent.inputs["dynamic_context_ui_transfer_hint"] == {
        "source": "selection",
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": "文本",
        "mode": "focus",
    }
    assert [step.step_id for step in selected_text.plan.tool_plan.steps] == [
        "copy-selected-dynamic-context",
        "discover_apps-desktop-state",
        "open-selected-discovered-app",
        "paste-context-into-selected-discovered-app",
        "verify-selected-discovered-app-action",
    ]
    assert _step_by_id(selected_text, "discover_apps-desktop-state").input_preview == {
        "query": "document",
        "limit": 20,
    }
    selected_text_requests = planner_tool_requests(
        "找一个文本编辑器，把选中的文字写进去",
        allowed_tools,
    )
    assert [request["tool"] for request in selected_text_requests] == [
        "desktop.safe_shortcut",
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]
    assert selected_text_requests[0]["input"] == {"action": "copy"}
    assert selected_text_requests[3]["input"] == {"action": "paste"}
    assert all("continue_to_model" not in request for request in selected_text_requests)


def test_runtime_planner_keeps_plain_document_transfer_off_report_generation() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
        "clipboard.read",
    ]

    plain_transfer = RuntimePlanner().decision(
        "找一个文档应用，把选中的文字写进去",
        allowed_tools=allowed_tools,
    )
    generated_report = RuntimePlanner().decision(
        "把选中的文字整理成报告写进一个文档应用",
        allowed_tools=allowed_tools,
    )

    assert plain_transfer.selected_intent.kind == "desktop_operation"
    assert plain_transfer.selected_intent.inputs["dynamic_context_ui_transfer_hint"] == {
        "source": "selection",
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": "文档",
        "mode": "focus",
    }
    assert [step.step_id for step in plain_transfer.plan.tool_plan.steps] == [
        "copy-selected-dynamic-context",
        "discover_apps-desktop-state",
        "open-selected-discovered-app",
        "paste-context-into-selected-discovered-app",
        "verify-selected-discovered-app-action",
    ]
    assert generated_report.selected_intent.kind == "report_generation"
    assert [request["tool"] for request in planner_tool_requests(
        "找一个文档应用，把选中的文字写进去",
        allowed_tools,
    )] == [
        "desktop.safe_shortcut",
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]


def test_runtime_planner_pastes_dynamic_context_into_named_apps() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "app.focus",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
        "clipboard.read",
    ]

    clipboard = RuntimePlanner().decision(
        "把剪贴板内容写进 Obsidian",
        allowed_tools=allowed_tools,
    )
    explicit_open = RuntimePlanner().decision(
        "打开 Obsidian，把剪贴板内容写进去",
        allowed_tools=allowed_tools,
    )

    assert clipboard.selected_intent.kind == "desktop_operation"
    assert clipboard.selected_intent.inputs["dynamic_context_ui_transfer_hint"] == {
        "source": "clipboard",
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": "Obsidian",
        "mode": "focus",
    }
    assert [step.step_id for step in clipboard.plan.tool_plan.steps] == [
        "discover-desktop-state",
        "open-or-focus-app",
        "paste-context-into-app",
        "verify-desktop-result",
    ]
    assert _step_by_id(clipboard, "open-or-focus-app").tool_name == "app.focus"
    assert _step_by_id(clipboard, "paste-context-into-app").input_preview == {
        "action": "paste"
    }
    clipboard_requests = planner_tool_requests(
        "把剪贴板内容写进 Obsidian",
        allowed_tools,
    )
    assert [request["tool"] for request in clipboard_requests] == [
        "desktop.list_apps",
        "app.focus",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]
    assert clipboard_requests[2]["input"] == {"action": "paste"}
    assert all(request["tool"] != "clipboard.read" for request in clipboard_requests)

    assert explicit_open.selected_intent.inputs["dynamic_context_ui_transfer_hint"] == {
        "source": "clipboard",
        "action": "transfer_context",
        "target_kind": "app_paste",
        "target": "",
        "app_name": "Obsidian",
        "mode": "open",
    }
    assert _step_by_id(explicit_open, "open-or-focus-app").tool_name == "app.open"
    explicit_open_requests = planner_tool_requests(
        "打开 Obsidian，把剪贴板内容写进去",
        allowed_tools,
    )
    assert [request["tool"] for request in explicit_open_requests] == [
        "desktop.list_apps",
        "app.open",
        "desktop.safe_shortcut",
        "desktop.ui_elements",
    ]
    assert explicit_open_requests[2]["input"] == {"action": "paste"}


def test_runtime_planner_discovers_chinese_generic_editor_apps_before_acting() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "desktop.active_window",
        "data.analyze",
        "workspace.read",
        "terminal.run",
        "artifact.write",
    ]

    cases = (
        ("打开文本编辑器", "document", "文本"),
        ("打开一个文本编辑器", "document", "文本"),
        ("打开代码编辑器", "code", "代码"),
        ("打开一个代码编辑器", "code", "代码"),
        ("打开表格应用", "spreadsheet", "表格"),
        ("打开电子表格软件", "spreadsheet", "电子表格"),
        ("打开图片编辑器", "image", "图片"),
        ("打开图片查看器", "image", "图片"),
        ("打开看图软件", "image", "看图"),
        ("打开 PDF 编辑器", "pdf", "PDF"),
        ("打开 PDF 阅读器", "pdf", "PDF"),
    )

    for prompt, query, description in cases:
        decision = RuntimePlanner().decision(prompt, allowed_tools=allowed_tools)

        assert decision.selected_intent.kind == "desktop_operation"
        assert decision.selected_intent.inputs["app_name_hint"] == ""
        assert decision.selected_intent.inputs["operation_hint"] == "discover_apps"
        assert decision.selected_intent.inputs["desktop_discovery_hint"] == {
            "action": "discover_apps",
            "query": query,
        }
        assert decision.selected_intent.inputs["app_capability_hint"] == {
            "query": query,
            "description": description,
        }
        assert [step.step_id for step in decision.plan.tool_plan.steps] == [
            "discover_apps-desktop-state",
            "open-selected-discovered-app",
            "verify-desktop-result",
        ]
        assert _step_by_id(decision, "verify-desktop-result").tool_name == (
            "desktop.active_window"
        )
        assert _step_by_id(decision, "verify-desktop-result").depends_on == [
            "open-selected-discovered-app"
        ]
        assert planner_tool_requests(prompt, allowed_tools) == (
            _selected_discovered_app_open_chain(query)
        )

    assert RuntimePlanner().decision(
        "用 Excel 分析 data/sales.csv 并输出报告",
        allowed_tools=allowed_tools,
    ).selected_intent.kind == "data_analysis"


def test_runtime_planner_routes_capability_app_search_to_desktop_operation() -> None:
    allowed_tools = [
        "desktop.list_apps",
        "app.open",
        "app.focus",
        "desktop.ui_elements",
        "desktop.click_ui_element",
        "desktop.safe_type_text",
        "desktop.search_submit",
    ]

    cases = (
        ("找一个图片设计应用搜索 logo 模板", "logo 模板", "搜索"),
        ("find an image design app and search logo templates", "logo templates", "Search"),
    )

    for prompt, query, target in cases:
        decision = RuntimePlanner().decision(prompt, allowed_tools=allowed_tools)

        assert decision.selected_intent.kind == "desktop_operation"
        assert decision.selected_intent.inputs["app_name_hint"] == ""
        assert decision.selected_intent.inputs["operation_hint"] == "discover_apps"
        assert decision.selected_intent.inputs["desktop_discovery_hint"] == {
            "action": "discover_apps",
            "query": "image",
        }
        assert decision.selected_intent.inputs["app_capability_hint"]["query"] == "image"
        assert decision.selected_intent.inputs["app_search_hint"] == {
            "query": query,
            "target": target,
        }
        assert [step.step_id for step in decision.plan.tool_plan.steps[:4]] == [
            "discover_apps-desktop-state",
            "open-selected-discovered-app",
            "focus-app-search-field",
            "type-app-search-query",
        ]
        assert _step_by_id(decision, "open-selected-discovered-app").input_preview == {
            "app_name": "<selected app from desktop.list_apps>",
            "selection_source": "desktop.list_apps",
            "query": "image",
        }
        assert _step_by_id(decision, "type-app-search-query").input_preview == {
            "text": query
        }
        requests = planner_tool_requests(prompt, allowed_tools)
        assert [request["tool"] for request in requests[:4]] == [
            "desktop.list_apps",
            "app.open",
            "desktop.click_ui_element",
            "desktop.safe_type_text",
        ]


