def test_runtime_planner_routes_flexible_communication_surface_phrasing() -> None:
    allowed_tools = [
        "app.focus_and_safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.submit_foreground",
    ]
    examples = [
        (
            "帮我在微信给文件传输助手说测试一下",
            {
                "app_name": "WeChat",
                "recipient": "文件传输助手",
                "body": "测试一下",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "send hello in Slack to yachiyo",
            {
                "app_name": "Slack",
                "recipient": "yachiyo",
                "body": "hello",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "message yachiyo in Slack hello",
            {
                "app_name": "Slack",
                "recipient": "yachiyo",
                "body": "hello",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "发微信给张三：你好",
            {
                "app_name": "WeChat",
                "recipient": "张三",
                "body": "你好",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "给张三发微信：你好",
            {
                "app_name": "WeChat",
                "recipient": "张三",
                "body": "你好",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "给 Alice 发微信说我晚点到",
            {
                "app_name": "WeChat",
                "recipient": "Alice",
                "body": "我晚点到",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "在 Slack 给 Alice 发消息说会议改到三点",
            {
                "app_name": "Slack",
                "recipient": "Alice",
                "body": "会议改到三点",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "在 Slack 给 Alice 发一条消息说会议改到三点",
            {
                "app_name": "Slack",
                "recipient": "Alice",
                "body": "会议改到三点",
                "mode": "focus",
                "send_action": "send",
            },
        ),
        (
            "给 Slack 的 yachiyo 发 hello",
            {
                "app_name": "Slack",
                "recipient": "yachiyo",
                "body": "hello",
                "mode": "focus",
                "send_action": "send",
            },
        ),
    ]

    for prompt, direct_hint in examples:
        decision = RuntimePlanner().decision(prompt, allowed_tools=allowed_tools)

        assert decision.selected_intent.kind == "communication"
        assert decision.selected_intent.inputs == {"direct_message_hint": direct_hint}

    app_scoped_target = RuntimePlanner().decision(
        "给 Slack 的 yachiyo 发 hello",
        allowed_tools=[
            "app.focus_and_safe_shortcut",
            "app.focus_and_safe_type_text",
            "desktop.search_submit",
            "desktop.submit_foreground",
        ],
    )
    assert app_scoped_target.plan.tool_plan.missing_capabilities == []
    assert _step_by_id(
        app_scoped_target,
        "type-communication-recipient",
    ).tool_name == "app.focus_and_safe_type_text"
    assert _step_by_id(
        app_scoped_target,
        "draft-communication-message",
    ).input_preview == {"app_name": "Slack", "text": "hello"}

    generic_decision = RuntimePlanner().decision(
        "发送消息给 Alice：今晚八点见",
        allowed_tools=allowed_tools,
    )
    assert generic_decision.selected_intent.kind == "communication"
    assert generic_decision.selected_intent.inputs == {
        "direct_message_hint": {
            "recipient": "Alice",
            "body": "今晚八点见",
            "mode": "focus",
            "send_action": "send",
            "channel": "message",
        }
    }


