def test_runtime_planner_routes_relative_reminder_to_schedule_capability(monkeypatch: Any) -> None:
    _freeze_schedule_now(monkeypatch, datetime(2026, 6, 30, 10, 0))
    tomorrow_0900 = f"{(date.today() + timedelta(days=1)).isoformat()}T09:00"
    tomorrow_1000 = f"{(date.today() + timedelta(days=1)).isoformat()}T10:00"
    today_1030 = "2026-06-30T10:30"
    today_1045 = "2026-06-30T10:45"
    today_1200 = "2026-06-30T12:00"
    next_monday = date.today() + timedelta(days=7 - date.today().weekday())
    next_monday_1000 = f"{next_monday.isoformat()}T10:00"
    decision = RuntimePlanner().decision(
        "提醒我明天买牛奶",
        allowed_tools=["reminders.create"],
    )
    generic_surface = RuntimePlanner().decision(
        "用任意可用的提醒应用提醒我明天买牛奶",
        allowed_tools=["reminders.create"],
    )
    generic_surface_without_verb = RuntimePlanner().decision(
        "用任意可用的提醒应用明天买牛奶",
        allowed_tools=["reminders.create"],
    )
    create_first = RuntimePlanner().decision(
        "创建明天上午10点开会的提醒",
        allowed_tools=["reminders.create"],
    )
    default_title_create = RuntimePlanner().decision(
        "给我创建一个明天上午十点的提醒",
        allowed_tools=["reminders.create"],
    )
    default_title_time_only = RuntimePlanner().decision(
        "明天上午十点提醒",
        allowed_tools=["reminders.create"],
    )
    create_prefixed_comma = RuntimePlanner().decision(
        "新建一个提醒，明天下午三点叫我提交周报",
        allowed_tools=["reminders.create"],
    )
    time_first_plain = RuntimePlanner().decision(
        "帮我下周一上午十点提醒团队复盘",
        allowed_tools=["reminders.create", "group.run"],
    )
    duration_cn = RuntimePlanner().decision(
        "30分钟后提醒我喝水",
        allowed_tools=["reminders.create"],
    )
    duration_default_title = RuntimePlanner().decision(
        "30分钟后提醒",
        allowed_tools=["reminders.create"],
    )
    half_hour_cn = RuntimePlanner().decision(
        "半小时后提醒我喝水",
        allowed_tools=["reminders.create"],
    )
    duration_en = RuntimePlanner().decision(
        "in 45 minutes remind me to stretch",
        allowed_tools=["reminders.create"],
    )
    duration_en_middle = RuntimePlanner().decision(
        "remind me in 2 hours to check the oven",
        allowed_tools=["reminders.create"],
    )

    assert decision.selected_intent.kind == "schedule"
    step = _step_by_id(decision, "create-schedule-item")
    assert step.tool_name == "reminders.create"
    assert step.input_preview == {"title": "买牛奶", "due_at": tomorrow_0900}
    for reminder_decision in (generic_surface, generic_surface_without_verb):
        assert reminder_decision.selected_intent.kind == "schedule"
        reminder_step = _step_by_id(reminder_decision, "create-schedule-item")
        assert reminder_step.tool_name == "reminders.create"
        assert reminder_step.input_preview == {"title": "买牛奶", "due_at": tomorrow_0900}
    assert create_first.selected_intent.kind == "schedule"
    create_first_step = _step_by_id(create_first, "create-schedule-item")
    assert create_first_step.tool_name == "reminders.create"
    assert create_first_step.input_preview == {
        "title": "开会",
        "due_at": tomorrow_1000,
    }
    assert default_title_create.selected_intent.kind == "schedule"
    assert _step_by_id(default_title_create, "create-schedule-item").input_preview == {
        "title": "提醒",
        "due_at": tomorrow_1000,
    }
    assert default_title_time_only.selected_intent.kind == "schedule"
    assert _step_by_id(default_title_time_only, "create-schedule-item").input_preview == {
        "title": "提醒",
        "due_at": tomorrow_1000,
    }
    assert create_prefixed_comma.selected_intent.kind == "schedule"
    assert _step_by_id(create_prefixed_comma, "create-schedule-item").input_preview == {
        "title": "提交周报",
        "due_at": f"{(date.today() + timedelta(days=1)).isoformat()}T15:00",
    }
    assert time_first_plain.selected_intent.kind == "schedule"
    time_first_plain_step = _step_by_id(time_first_plain, "create-schedule-item")
    assert time_first_plain_step.tool_name == "reminders.create"
    assert time_first_plain_step.input_preview == {
        "title": "团队复盘",
        "due_at": next_monday_1000,
    }
    assert duration_cn.selected_intent.kind == "schedule"
    assert _step_by_id(duration_cn, "create-schedule-item").input_preview == {
        "title": "喝水",
        "due_at": today_1030,
    }
    assert _step_by_id(duration_default_title, "create-schedule-item").input_preview == {
        "title": "提醒",
        "due_at": today_1030,
    }
    assert _step_by_id(half_hour_cn, "create-schedule-item").input_preview == {
        "title": "喝水",
        "due_at": today_1030,
    }
    assert _step_by_id(duration_en, "create-schedule-item").input_preview == {
        "title": "stretch",
        "due_at": today_1045,
    }
    assert _step_by_id(duration_en_middle, "create-schedule-item").input_preview == {
        "title": "check the oven",
        "due_at": today_1200,
    }


def test_runtime_planner_falls_back_to_future_task_for_timed_reminders() -> None:
    tomorrow_0900 = f"{(date.today() + timedelta(days=1)).isoformat()}T09:00"
    scheduled_epoch = datetime.fromisoformat(tomorrow_0900).timestamp()
    decision = RuntimePlanner().decision(
        "提醒我明天买牛奶",
        allowed_tools=["future_task.schedule"],
    )
    untimed = RuntimePlanner().decision(
        "创建提醒事项：买牛奶",
        allowed_tools=["future_task.schedule"],
    )

    assert decision.selected_intent.kind == "schedule"
    step = _step_by_id(decision, "create-schedule-item")
    assert step.tool_name == "future_task.schedule"
    assert step.input_preview == {
        "title": "买牛奶",
        "prompt": "提醒用户：买牛奶。原始请求：提醒我明天买牛奶",
        "scheduled_at_epoch": scheduled_epoch,
    }
    assert step.approval_required is True
    untimed_step = _step_by_id(untimed, "create-schedule-item")
    assert untimed_step.tool_name is None
    assert untimed_step.status == "unavailable"


def test_runtime_planner_schedules_future_runnable_runs(monkeypatch: Any) -> None:
    _freeze_schedule_now(monkeypatch, datetime(2026, 6, 30, 10, 0))
    tomorrow_1500 = f"{(date.today() + timedelta(days=1)).isoformat()}T15:00"
    tomorrow_1500_epoch = datetime.fromisoformat(tomorrow_1500).timestamp()
    today_1030_epoch = datetime.fromisoformat("2026-06-30T10:30").timestamp()
    workflow = RuntimePlanner().decision(
        "明天下午三点帮我运行 Daily Summary workflow",
        allowed_tools=["future_task.schedule", "workflow.start"],
    )
    no_future_task = RuntimePlanner().decision(
        "明天下午三点帮我运行 Daily Summary workflow",
        allowed_tools=["workflow.start"],
    )
    group = RuntimePlanner().decision(
        "30分钟后运行 Research Team group",
        allowed_tools=["future_task.schedule", "group.run"],
    )

    assert workflow.selected_intent.kind == "schedule"
    assert workflow.selected_intent.inputs == {
        "scheduled_runnable": True,
        "target_name_hint": "Daily Summary",
    }
    workflow_step = _step_by_id(workflow, "create-schedule-item")
    assert workflow_step.tool_name == "future_task.schedule"
    assert workflow_step.input_preview == {
        "title": "运行 Daily Summary workflow",
        "prompt": "运行 Daily Summary workflow",
        "scheduled_at_epoch": tomorrow_1500_epoch,
        "runnable_name": "Daily Summary",
    }
    assert workflow_step.approval_required is True

    no_future_task_step = _step_by_id(no_future_task, "create-schedule-item")
    assert no_future_task.selected_intent.kind == "schedule"
    assert no_future_task_step.tool_name is None
    assert no_future_task_step.status == "unavailable"

    assert group.selected_intent.kind == "schedule"
    group_step = _step_by_id(group, "create-schedule-item")
    assert group_step.tool_name == "future_task.schedule"
    assert group_step.input_preview == {
        "title": "运行 Research Team group",
        "prompt": "运行 Research Team group",
        "scheduled_at_epoch": today_1030_epoch,
        "runnable_name": "Research Team",
    }


