def test_planner_tool_requests_maps_system_control_plan() -> None:
    requests = planner_tool_requests(
        "打开屏保",
        allowed_tools=["system.screen_saver_start"],
    )

    assert requests == [
        {
            "protocol": "json_fallback",
            "tool": "system.screen_saver_start",
            "input": {},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        }
    ]

    assert planner_tool_requests(
        "open sound settings",
        allowed_tools=["system.settings_open"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "system.settings_open",
            "input": {"target": "声音"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        }
    ]
    assert planner_tool_requests(
        "打开系统设置看看有哪些选项",
        allowed_tools=["system.settings_open", "desktop.ui_elements"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "system.settings_open",
            "input": {"target": "系统设置"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        },
        {
            "protocol": "json_fallback",
            "tool": "desktop.ui_elements",
            "input": {"role_filter": "", "limit": 80},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        },
    ]
    assert planner_tool_requests(
        "在系统设置里打开蓝牙",
        allowed_tools=["app.open", "desktop.ui_elements"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "app.open",
            "input": {"app_name": "System Settings"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        },
        {
            "protocol": "json_fallback",
            "tool": "desktop.ui_elements",
            "input": {"limit": 80},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
            "continue_to_model": True,
        },
    ]
    assert planner_tool_requests(
        "把系统音量调到 50%",
        allowed_tools=["system.volume"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "system.volume",
            "input": {"action": "set", "level": 50},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        },
        {
            "protocol": "json_fallback",
            "tool": "system.volume",
            "input": {"action": "status"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
            "continue_to_model": True,
        },
    ]
    assert planner_tool_requests(
        "当前音量多少",
        allowed_tools=["system.volume"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "system.volume",
            "input": {"action": "status"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
        }
    ]
    assert planner_execution_tool_requests(
        [
            {
                "protocol": "tool_calls",
                "tool": "system.volume",
                "input": {"action": "mute"},
                "tool_call_id": "call_volume",
            }
        ],
        allowed_tools=["system.volume"],
    ) == [
        {
            "protocol": "tool_calls",
            "tool": "system.volume",
            "input": {"action": "mute"},
            "tool_call_id": "call_volume",
        },
        {
            "protocol": "json_fallback",
            "tool": "system.volume",
            "input": {"action": "status"},
            "source": "runtime_verification",
            "planning_reason": "runtime_system_control_verification",
            "continue_to_model": True,
        },
    ]
    assert planner_execution_tool_requests(
        [
            {
                "protocol": "tool_calls",
                "tool": "system.volume",
                "input": {"action": "set", "level": 30},
                "tool_call_id": "call_volume",
            },
            {
                "protocol": "tool_calls",
                "tool": "desktop.active_window",
                "input": {},
                "tool_call_id": "call_window",
            },
        ],
        allowed_tools=["system.volume", "desktop.active_window"],
    ) == [
        {
            "protocol": "tool_calls",
            "tool": "system.volume",
            "input": {"action": "set", "level": 30},
            "tool_call_id": "call_volume",
        },
        {
            "protocol": "tool_calls",
            "tool": "desktop.active_window",
            "input": {},
            "tool_call_id": "call_window",
        },
        {
            "protocol": "json_fallback",
            "tool": "system.volume",
            "input": {"action": "status"},
            "source": "runtime_verification",
            "planning_reason": "runtime_system_control_verification",
            "continue_to_model": True,
        },
    ]
    app_open_request = {
        "protocol": "tool_calls",
        "tool": "app.open",
        "input": {"app_name": "Music"},
        "tool_call_id": "call_open",
    }
    assert planner_execution_tool_requests(
        [app_open_request],
        allowed_tools=["app.open", "desktop.active_window"],
    ) == [app_open_request]
    assert runtime_execution_verified_tool_requests(
        [app_open_request],
        allowed_tools=["app.open", "desktop.active_window"],
        include_model_app_foreground=True,
    ) == [
        app_open_request,
        {
            "protocol": "json_fallback",
            "tool": "desktop.active_window",
            "input": {},
            "source": "runtime_verification",
            "planning_reason": "runtime_desktop_app_foreground_verification",
            "continue_to_model": True,
            "requires_observation": True,
            "runtime_stage": "verify",
            "runtime_role": "verify_result",
            "replan_triggers": ["verification_failed"],
            "target_app_name": "Music",
        },
    ]
    app_click_request = {
        "protocol": "tool_calls",
        "tool": "app.open_and_click_ui_element",
        "input": {"app_name": "Music", "target": "Play"},
        "tool_call_id": "call_click",
    }
    assert runtime_execution_verified_tool_requests(
        [app_click_request],
        allowed_tools=["app.open_and_click_ui_element", "desktop.ui_elements"],
        include_model_app_foreground=True,
    ) == [
        app_click_request,
        {
            "protocol": "json_fallback",
            "tool": "desktop.ui_elements",
            "input": {"limit": 80, "app_name": "Music"},
            "source": "runtime_verification",
            "planning_reason": "runtime_desktop_app_operation_verification",
            "continue_to_model": True,
            "requires_observation": True,
            "runtime_stage": "verify",
            "runtime_role": "verify_result",
            "replan_triggers": ["verification_failed"],
            "target_app_name": "Music",
        },
    ]
    desktop_click_request = {
        "protocol": "tool_calls",
        "tool": "desktop.click_ui_element",
        "input": {"target": "Play"},
        "tool_call_id": "call_desktop_click",
    }
    assert runtime_execution_verified_tool_requests(
        [desktop_click_request],
        allowed_tools=["desktop.click_ui_element", "desktop.ui_elements"],
        include_model_app_foreground=True,
    ) == [
        desktop_click_request,
        {
            "protocol": "json_fallback",
            "tool": "desktop.ui_elements",
            "input": {"limit": 80},
            "source": "runtime_verification",
            "planning_reason": "runtime_desktop_app_operation_verification",
            "continue_to_model": True,
            "requires_observation": True,
            "runtime_stage": "verify",
            "runtime_role": "verify_result",
            "replan_triggers": ["verification_failed"],
        },
    ]
    assert planner_tool_requests(
        "open sound settings",
        allowed_tools=["app.open"],
    ) == [
        {
            "protocol": "json_fallback",
            "tool": "app.open",
            "input": {"app_name": "System Settings"},
            "source": "runtime_planner",
            "planning_reason": "planner_fallback_system_control",
            "continue_to_model": True,
        }
    ]


