def test_planner_tool_requests_discovers_data_source_for_analysis() -> None:
    scoped_requests = planner_tool_requests(
        "分析 Downloads 里的销售数据并输出报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    recent_download_data_requests = planner_tool_requests(
        "分析最近下载的数据并生成图表报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    recent_download_csv_requests = planner_tool_requests(
        "分析最近下载的 CSV 并生成图表报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    named_download_file_requests = planner_tool_requests(
        "分析刚刚下载的 sales.csv 并生成报告",
        allowed_tools=["data.analyze", "workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    named_xlsx_requests = planner_tool_requests(
        "查找电脑上叫 budget 的 xlsx 并分析成报告",
        allowed_tools=["data.analyze", "workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    named_scoped_csv_requests = planner_tool_requests(
        "找 Downloads 里叫 sales 的 csv 并分析成报告",
        allowed_tools=["data.analyze", "workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    english_named_xlsx_requests = planner_tool_requests(
        "find the xlsx named budget on my computer and analyze it into a report",
        allowed_tools=["data.analyze", "workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    generic_requests = planner_tool_requests(
        "分析数据并输出报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    latest_csv_requests = planner_tool_requests(
        "找一下 Downloads 里最新的 csv，分析趋势并输出 markdown 报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    bare_csv_requests = planner_tool_requests(
        "分析最近的csv并生成图表",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )
    xlsx_requests = planner_tool_requests(
        "分析桌面上的 xlsx 并输出报告",
        allowed_tools=["workspace.list", "workspace.read", "terminal.run", "artifact.write"],
    )

    assert scoped_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Downloads"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert recent_download_data_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Downloads", "selection": "latest"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert recent_download_csv_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Downloads", "pattern": "*.csv", "file_type": "csv", "selection": "latest"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert named_download_file_requests == [
        {
            "protocol": "json_fallback",
            "tool": "data.analyze",
            "input": _data_analysis_preview("Downloads/sales.csv", "csv"),
            "source": "runtime_planner",
            "planning_reason": "planner_builtin_data_analysis",
        }
    ]
    assert named_xlsx_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"pattern": "*budget*.xlsx", "file_type": "xlsx"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
        },
        {
            "protocol": "json_fallback",
            "tool": "data.analyze",
            "input": {
                **_data_analysis_preview("<selected file from workspace.list>", "xlsx"),
                "selection_source": "workspace.list",
                "pattern": "*budget*.xlsx",
            },
            "source": "runtime_planner",
            "planning_reason": "planner_builtin_data_analysis",
        },
    ]
    assert named_scoped_csv_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Downloads", "pattern": "*sales*.csv", "file_type": "csv"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
        },
        {
            "protocol": "json_fallback",
            "tool": "data.analyze",
            "input": {
                **_data_analysis_preview("<selected file from workspace.list>", "csv"),
                "selection_source": "workspace.list",
                "source_scope": "Downloads",
                "pattern": "*sales*.csv",
            },
            "source": "runtime_planner",
            "planning_reason": "planner_builtin_data_analysis",
        },
    ]
    assert english_named_xlsx_requests == named_xlsx_requests
    assert xlsx_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Desktop", "pattern": "*.xlsx", "file_type": "xlsx"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert latest_csv_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"path": "Downloads", "pattern": "*.csv", "file_type": "csv", "selection": "latest"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert bare_csv_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {"pattern": "*.csv", "file_type": "csv", "selection": "latest"},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]
    assert generic_requests == [
        {
            "protocol": "json_fallback",
            "tool": "workspace.list",
            "input": {},
            "source": "runtime_planner",
            "planning_reason": "planner_prefetch_data_source",
            "continue_to_model": True,
        }
    ]


