def test_runtime_planner_routes_dynamic_context_ui_transfers() -> None:
    allowed = [
        "desktop.safe_shortcut",
        "desktop.click_ui_element",
        "app.open",
        "app.focus",
        "app.focus_and_safe_shortcut",
        "app.open_and_safe_shortcut",
        "app.focus_and_click_ui_element",
        "app.open_and_click_ui_element",
        "desktop.ui_elements",
        "desktop.active_window",
        "screen.capture",
    ]
    selected_copy = {
        "protocol": "json_fallback",
        "tool": "desktop.safe_shortcut",
        "input": {"action": "copy"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    current_page_link_copy = {
        "protocol": "json_fallback",
        "tool": "desktop.safe_shortcut",
        "input": {"action": "copy_current_page_link"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    current_content_copy = [
        {
            "protocol": "json_fallback",
            "tool": "desktop.safe_shortcut",
            "input": {"action": "select_all"},
            "source": "runtime_planner",
            "planning_reason": "planner_desktop_operation",
        },
        selected_copy,
    ]
    paste = {
        "protocol": "json_fallback",
        "tool": "desktop.safe_shortcut",
        "input": {"action": "paste"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    foreground_search_click = {
        "protocol": "json_fallback",
        "tool": "desktop.click_ui_element",
        "input": {"target": "搜索", "role_filter": "text", "limit": 80, "click_count": 1},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    foreground_address_click = {
        "protocol": "json_fallback",
        "tool": "desktop.click_ui_element",
        "input": {"target": "地址", "role_filter": "text", "limit": 80, "click_count": 1},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    slack_focus = {
        "protocol": "json_fallback",
        "tool": "app.focus",
        "input": {"app_name": "Slack"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    slack_open = {
        "protocol": "json_fallback",
        "tool": "app.open",
        "input": {"app_name": "Slack"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    obsidian_focus = {
        "protocol": "json_fallback",
        "tool": "app.focus",
        "input": {"app_name": "Obsidian"},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }
    verify_ui = {
        "protocol": "json_fallback",
        "tool": "desktop.ui_elements",
        "input": {},
        "source": "runtime_planner",
        "planning_reason": "planner_desktop_operation",
    }

    cases = (
        ("复制当前网页内容", [*current_content_copy]),
        ("把当前页面内容复制到剪贴板", [*current_content_copy]),
        ("把当前网页链接粘贴到 Slack", [
            current_page_link_copy,
            slack_focus,
            paste,
            verify_ui,
        ]),
        ("在 Slack 粘贴当前页面内容", [
            *current_content_copy,
            slack_focus,
            paste,
            verify_ui,
        ]),
        ("打开 Slack 粘贴当前页面内容", [
            *current_content_copy,
            slack_open,
            paste,
            verify_ui,
        ]),
        ("把当前网页内容写进 Obsidian", [
            *current_content_copy,
            obsidian_focus,
            paste,
            verify_ui,
        ]),
        ("把当前网页内容保存到 Obsidian 新笔记", [
            *current_content_copy,
            obsidian_focus,
            paste,
            verify_ui,
        ]),
        ("把当前网页链接写进 Obsidian", [
            current_page_link_copy,
            obsidian_focus,
            paste,
            verify_ui,
        ]),
        ("把剪贴板内容粘贴到 Slack", [
            slack_focus,
            paste,
            verify_ui,
        ]),
        ("把选中的内容填到当前输入框", [selected_copy, paste, verify_ui]),
        ("把剪贴板内容填到当前输入框", [paste, verify_ui]),
        ("把剪贴板内容输入到搜索框", [foreground_search_click, paste, verify_ui]),
        ("把当前网页链接输入到地址栏", [
            current_page_link_copy,
            foreground_address_click,
            paste,
            verify_ui,
        ]),
        ("把当前页面内容输入到搜索框", [
            *current_content_copy,
            foreground_search_click,
            paste,
            verify_ui,
        ]),
        ("把当前网页链接输入到 Slack 搜索框", [
            current_page_link_copy,
            slack_focus,
            foreground_search_click,
            paste,
            verify_ui,
        ]),
        ("把当前页面内容输入到 Slack 搜索框", [
            *current_content_copy,
            slack_focus,
            foreground_search_click,
            paste,
            verify_ui,
        ]),
        ("打开 Slack 搜索框输入选中的内容", [
            selected_copy,
            slack_open,
            foreground_search_click,
            paste,
            verify_ui,
        ]),
    )
    for prompt, expected_requests in cases:
        decision = RuntimePlanner().decision(prompt, allowed_tools=allowed)

        assert decision.selected_intent.kind == "desktop_operation"
        assert decision.selected_intent.inputs["operation_hint"] == "dynamic_context_ui_transfer"
        assert planner_direct_tool_requests(prompt, allowed) == expected_requests

    blocked = RuntimePlanner().decision(
        "把当前页面内容输入到当前输入框",
        allowed_tools=[*allowed, "browser.type_text"],
    )
    assert blocked.selected_intent.kind == "general"
    assert planner_direct_tool_requests(
        "把当前页面内容输入到当前输入框",
        [*allowed, "browser.type_text"],
    ) == []


def test_runtime_planner_marks_foreground_blocked_desktop_steps_unavailable() -> None:
    prompt = "打开 PixelForge 并点击导出按钮"
    allowed = [
        "desktop.list_apps",
        "app.open",
        "app.open_and_click_ui_element",
        "screen.capture",
    ]
    metadata = {
        "desktop_blocking_conditions_by_capability": {
            "foreground_activation": ["foreground_focus_unavailable"],
        }
    }
    decision = RuntimePlanner().decision(
        prompt,
        allowed_tools=allowed,
        metadata=metadata,
    )

    discover = _step_by_id(decision, "discover-desktop-state")
    operate = _step_by_id(decision, "operate-foreground-ui")
    verify = _step_by_id(decision, "verify-desktop-result")

    assert decision.selected_intent.kind == "desktop_operation"
    assert discover.status == "planned"
    assert discover.tool_name == "desktop.list_apps"
    assert operate.tool_name == "app.open_and_click_ui_element"
    assert operate.status == "unavailable"
    assert operate.input_preview["blocking_conditions"] == ["foreground_focus_unavailable"]
    assert "foreground_focus_unavailable" in operate.reason
    assert verify.status == "planned"
    assert decision.plan.tool_plan.missing_capabilities == ["desktop.ui_operation"]
    assert planner_tool_requests(prompt, allowed, metadata=metadata) == []
    assert planner_direct_tool_requests(prompt, allowed, metadata=metadata) == []

    flat_metadata_decision = RuntimePlanner().decision(
        prompt,
        allowed_tools=allowed,
        metadata={"blocking_conditions": "foreground_focus_unavailable desktop_session_locked"},
    )

    assert _step_by_id(flat_metadata_decision, "operate-foreground-ui").status == "unavailable"


