def test_runtime_execution_envelope_projects_decision_into_executable_requests() -> None:
    allowed_tools = [
        "desktop.inspect_app",
        "app.open_and_click_ui_element",
        "desktop.ui_elements",
    ]
    decision = RuntimePlanner().decision(
        "打开 PixelForge 并点击导出",
        allowed_tools=allowed_tools,
    )

    requests = planner_tool_requests_for_decision(decision, allowed_tools)
    envelope = runtime_execution_envelope_from_decision(
        decision,
        allowed_tools=allowed_tools,
    )

    assert [request["step_id"] for request in requests] == [
        "inspect-app",
        "operate-foreground-ui",
        "verify-desktop-result",
    ]
    assert envelope is not None
    assert envelope.decision_id == decision.decision_id
    assert envelope.plan_id == decision.plan.plan_id
    assert envelope.task_core is not None
    assert envelope.task_core.core_id == decision.plan.task_core.core_id
    assert envelope.runtime_doctrine == "discover_operate_verify"
    assert envelope.runtime_stage_counts == {
        "discover": 1,
        "operate": 1,
        "verify": 1,
    }
    assert envelope.replan_signal_count == len(decision.plan.task_core.replan_signals)
    assert [request.tool_name for request in envelope.requests] == [
        "desktop.inspect_app",
        "app.open_and_click_ui_element",
        "desktop.ui_elements",
    ]
    assert [request.runtime_stage for request in envelope.requests] == [
        "discover",
        "operate",
        "verify",
    ]
    assert envelope.requests[1].step_id == "operate-foreground-ui"
    assert envelope.requests[1].capability_id == "desktop.ui_operation"
    assert envelope.requests[1].approval_required is True
    assert envelope.requests[1].runtime_doctrine == "discover_operate_verify"
    assert envelope.requests[1].runtime_role == "click_ui"
    assert envelope.requests[1].requires_post_action_verification is True
    assert envelope.requests[1].replan_triggers == ["verification_failed"]
    assert envelope.requests[1].replan_signal_ids
    assert envelope.requests[1].decision_id == decision.decision_id
    assert envelope.requests[1].plan_id == decision.plan.plan_id
    assert envelope.requests[1].intent_kind == "desktop_operation"
    assert envelope.requests[1].core_id == decision.plan.task_core.core_id
    assert (
        envelope.requests[1].workspace_id
        == decision.plan.task_core.workspace.workspace_id
    )
    assert envelope.requests[1].task_todo["step_id"] == "operate-foreground-ui"
    assert envelope.requests[1].task_todo["tool_name"] == "app.open_and_click_ui_element"
    assert envelope.requests[1].task_checkpoints[0]["after_step_id"] == (
        "operate-foreground-ui"
    )
    assert envelope.requests[1].task_workspace_items[0]["source_step_id"] == (
        "operate-foreground-ui"
    )
    assert envelope.requests[2].depends_on == ["operate-foreground-ui"]
    assert envelope.requests[2].task_verification_targets[0]["step_id"] == (
        "operate-foreground-ui"
    )
    projected_requests = runtime_execution_requests_from_envelope_payload(
        envelope.model_dump(mode="json"),
        allowed_tools=allowed_tools,
    )
    assert [request["tool"] for request in projected_requests] == [
        "desktop.inspect_app",
        "app.open_and_click_ui_element",
        "desktop.ui_elements",
    ]
    assert projected_requests[1]["step_id"] == "operate-foreground-ui"
    assert projected_requests[1]["capability_id"] == "desktop.ui_operation"
    assert projected_requests[1]["approval_required"] is True
    assert projected_requests[1]["runtime_stage"] == "operate"
    assert projected_requests[1]["runtime_role"] == "click_ui"
    assert projected_requests[1]["requires_post_action_verification"] is True
    assert projected_requests[1]["replan_triggers"] == ["verification_failed"]
    assert projected_requests[1]["replan_signal_ids"] == envelope.requests[1].replan_signal_ids
    assert projected_requests[1]["decision_id"] == decision.decision_id
    assert projected_requests[1]["plan_id"] == decision.plan.plan_id
    assert projected_requests[1]["core_id"] == decision.plan.task_core.core_id
    assert (
        projected_requests[1]["workspace_id"]
        == decision.plan.task_core.workspace.workspace_id
    )
    assert projected_requests[1]["task_todo"]["step_id"] == "operate-foreground-ui"
    assert projected_requests[1]["task_todo"]["tool_name"] == "app.open_and_click_ui_element"
    assert projected_requests[1]["task_checkpoints"][0]["after_step_id"] == "operate-foreground-ui"
    assert (
        projected_requests[1]["task_workspace_items"][0]["source_step_id"]
        == "operate-foreground-ui"
    )
    assert projected_requests[2]["runtime_stage"] == "verify"
    assert projected_requests[2]["task_verification_targets"][0]["step_id"] == (
        "operate-foreground-ui"
    )
    assert projected_requests[2]["task_verification_targets"][0]["todo"]["step_id"] == (
        "operate-foreground-ui"
    )
    assert projected_requests[2]["task_verification_targets"][0]["checkpoints"][0][
        "after_step_id"
    ] == "operate-foreground-ui"


