def test_agent_studio_service_projects_full_code_and_file_execution_plans() -> None:
    class StudioPort:
        pass

    service = AgentStudioService(StudioPort())
    code_envelope = service.plan_execution(
        "修改 README 中的安装说明并运行测试",
        allowed_tools=["workspace.read", "workspace.write_patch", "terminal.run", "artifact.write"],
        metadata={"surface": "studio"},
    )
    file_envelope = service.plan_execution(
        "整理 Downloads 里的 pdf 文件",
        allowed_tools=["workspace.list", "fs.move_file", "artifact.write"],
        metadata={"surface": "studio"},
    )

    assert [request.tool_name for request in code_envelope.requests] == [
        "workspace.read",
        "terminal.run",
        "workspace.write_patch",
        "terminal.run",
    ]
    assert [request.step_id for request in code_envelope.requests] == [
        "read-code-target-file",
        "run-code-diagnostic",
        "apply-code-changes",
        "verify-code-changes",
    ]
    assert code_envelope.requests[2].task_todo["step_id"] == "apply-code-changes"
    assert code_envelope.requests[2].task_checkpoints[0]["after_step_id"] == (
        "apply-code-changes"
    )
    assert code_envelope.requests[3].task_verification_targets[0]["step_id"] == (
        "apply-code-changes"
    )
    assert code_envelope.requests[0].input == {"path": "README.md"}
    assert code_envelope.requests[1].approval_required is True
    assert code_envelope.requests[2].approval_required is True
    assert [request.tool_name for request in file_envelope.requests] == [
        "workspace.list",
        "artifact.write",
        "fs.move_file",
    ]
    assert file_envelope.requests[2].approval_required is True


def test_yachiyo_agent_service_uses_fake_runtime_planner_port() -> None:
    class FakePlannerPort:
        def plan_chat_task(
            self,
            prompt: str,
            *,
            allowed_tools: Iterable[str] | None = None,
            metadata: Mapping[str, Any] | None = None,
        ) -> dict[str, Any]:
            return RuntimePlanner().decision(
                prompt,
                allowed_tools=allowed_tools,
                metadata=metadata,
            ).model_dump(mode="json")

    decision = YachiyoAgentService(FakePlannerPort()).plan_chat_task(
        "打开 PixelForge 并点击导出",
        allowed_tools=["desktop.running_apps", "app.open", "desktop.click_ui_element"],
    )

    assert isinstance(decision, PlannerDecisionSnapshot)
    assert decision.selected_intent.kind == "desktop_operation"
    assert _step_by_id(decision, "open-or-focus-app").input_preview == {"app_name": "PixelForge"}


def test_runtime_planner_keeps_app_search_as_desktop_operation_when_analysis_is_query_text() -> None:
    decision = RuntimePlanner().decision("打开 Obsidian 并搜索昨天的数据分析笔记")
    envelope = runtime_execution_envelope_from_decision(decision, full_plan=True)

    assert decision.selected_intent.kind == "desktop_operation"
    assert _step_by_id(decision, "open-or-focus-app").input_preview == {"app_name": "Obsidian"}
    assert _step_by_id(decision, "type-app-search-query").input_preview == {
        "text": "昨天的数据分析笔记"
    }
    assert envelope is not None
    assert [request.tool_name for request in envelope.requests] == [
        "desktop.list_apps",
        "app.open",
        "app.focus",
        "app.open_and_safe_shortcut",
        "desktop.safe_type_text",
        "desktop.search_submit",
        "desktop.ui_elements",
    ]


def test_runtime_planner_escalates_app_search_to_data_analysis_when_user_requests_analysis() -> None:
    decision = RuntimePlanner().decision("打开 Obsidian 搜索 sales 数据，然后分析成报告")

    assert decision.selected_intent.kind == "data_analysis"
    assert _step_by_id(decision, "type-app-search-query").input_preview == {"text": "sales 数据"}
    assert _step_by_id(decision, "analyze-data-context").tool_name == "data.analyze"


def test_runtime_planner_projects_current_app_paste_as_focus_safe_shortcut() -> None:
    decision = RuntimePlanner().decision("在任意当前打开的表格应用里粘贴这段结果")
    envelope = runtime_execution_envelope_from_decision(decision, full_plan=True)

    assert decision.selected_intent.kind == "desktop_operation"
    assert _step_by_id(decision, "open-selected-discovered-app").tool_name == (
        "app.focus_and_safe_shortcut"
    )
    assert _step_by_id(decision, "open-selected-discovered-app").input_preview["action"] == "paste"
    assert envelope is not None
    assert [request.tool_name for request in envelope.requests].count(
        "app.focus_and_safe_shortcut"
    ) == 1
    paste_request = next(
        request
        for request in envelope.requests
        if request.tool_name == "app.focus_and_safe_shortcut"
    )
    assert paste_request.runtime_stage == "operate"
    assert paste_request.runtime_role == "shortcut_ui"
    assert paste_request.task_todo["metadata"]["runtime_role"] == "shortcut_ui"
